// A run ends only from confirmed league records. Dialog reads never spend a life.
var rebirthRulesPage=0,rebirthHistoryPage=0,rebirthPage='current',rebirthReturn=null,rebirthSeen=new Set(),rebirthOffer=null,rebirthBusy=false,rebirthSelectedMemory='calm',rebirthError='';
const rebirthDialog=document.createElement('dialog');rebirthDialog.id='rebirth-dialog';rebirthDialog.setAttribute('aria-labelledby','rebirth-title');document.body.append(rebirthDialog);
function closeRebirth(){rebirthDialog.close();if(rebirthReturn?.isConnected)rebirthReturn.focus({preventScroll:true});else $('mobile-dashboard-toggle')?.focus({preventScroll:true});}
function rebirthHint(r){return r.status==='sacked'?'계약 종료 · 환생 선택':r.status==='returned'?'1부 귀환 · 이번 삶의 결말':r.pending?'회차 면담 · 답변 필요':r.warning?'최후통첩 · '+r.warning.remaining+'경기 남음':'이번 삶 · 여유 '+r.confidence;}
function openRebirth(page='current',trigger=document.activeElement){if(typeof practiceSession!=='undefined'&&practiceSession)return;pauseForPlanning();rebirthReturn=trigger;rebirthPage=page;rebirthError='';renderRebirthDialog();if(!rebirthDialog.open)rebirthDialog.showModal();$('rebirth-title').focus({preventScroll:true});}
function rebirthMutation(fn){if(rebirthBusy)return;try{rebirthBusy=true;rebirthError='';season=fn();state=season.match;save();if(!canSave)rebirthError='저장 공간이 부족합니다. 저장 파일을 받아 두세요.';render();renderRebirthDialog();}catch(e){rebirthError=e.message;renderRebirthDialog();}finally{rebirthBusy=false;}}
function reincarnate(){
 if(rebirthBusy)return;rebirthBusy=true;rebirthError='';renderRebirthDialog();
 requestAnimationFrame(()=>setTimeout(()=>{try{
  const next=Rebirth.restart(season,rebirthSelectedMemory),text=CampaignFile.stringify({season:next,view:'club',media:{...mediaPrefs},playback:{...playbackPrefs}});
  pendingImport=CampaignFile.read(text);pendingImportText=text;if(!applyCampaignImport('새로운 삶이 시작됩니다.'))throw Error(portabilityError||'새 회차를 저장하지 못했습니다.');
  rebirthSeen=new Set();rebirthOffer=null;managerIntroBypass=false;managerGuideActive=false;managerGuideWaiting=null;rebirthDialog.close();appSessionStarted=false;view='club';launchHasCampaign=true;render();$('launch-continue').focus({preventScroll:true});
 }catch(e){rebirthError=e.message;rebirthPage='confirm';renderRebirthDialog();}finally{rebirthBusy=false;if(rebirthDialog.open)renderRebirthDialog();}},0));
}
function renderRebirthDialog(){
 const r=Rebirth.read(season),esc=escapeText,ended=r.enabled&&r.status!=='active';let title='이번 삶의 계약',content='',actions='';
 const button=(id,label,extra='')=>'<button type="button" data-rebirth="'+id+'" '+extra+'>'+esc(label)+'</button>';
 if(!r.enabled&&rebirthPage!=='rules'){title='끝이 있는 감독 생활';content='<p class="rebirth-line">“승리만이 아니라, 실패도 다음 삶에 남습니다.”</p><p>현재 구단과 선수는 그대로 두고, 지금 이후의 리그 결과부터 경질 압박을 적용합니다. 과거 패배를 소급해 불이익을 주지 않습니다.</p><ul><li>승리 +4 · 무승부 −3 · 패배 −8</li><li>여유 20 이하: 다음 3경기에서 승점 3점</li><li>최후통첩 실패: 계약 종료 → 무료 환생</li></ul>';const playing=state&&state.phase!=='prep';actions=button('enable','이 구단에서 도전 시작',playing?'disabled':'')+button('close',playing?'진행 중 경기부터 마치기':'구단으로 돌아가기');}
 else if(rebirthPage==='rules'){title='환생 도전 규칙';content='<ol><li>이사회 여유 60으로 시작합니다. 리그 승리 +4, 무승부 −3, 패배 −8. 컵 결과는 여유를 바꾸지 않습니다.</li><li>6경기마다 구단주·팬·코치와 약속을 정합니다. 새 삶의 구단주 요구는 성격마다 다르며, 다음 리그 3경기 결과로 판정합니다. 기존 삶의 약속은 그대로 이어갑니다.</li><li>여유가 20 이하이면 최후통첩. 다음 3경기에서 승점 3점을 얻으면 최소 28로 회복합니다. 못 얻으면 경질됩니다.</li><li>환생은 무료입니다. 선수·자금·일정은 초기화하고 회차 기록과 선택한 기억을 이어 갑니다.</li><li>두 번째 삶부터 기억으로 경질을 한 번 유예할 수 있습니다. 여유 35로 돌아오며 승패 기록은 그대로입니다.</li><li>1부 승격을 확정하고 모든 시즌 일정을 마치면 귀환 엔딩입니다.</li></ol><p class="rebirth-note">결제 기능은 연결되지 않았습니다. 현재 환생과 기억의 유예는 무료입니다.</p>';actions=button('current','이번 삶으로');}
 else if(rebirthPage==='history'){title='이전 삶의 기억';content=r.previous.length?'<div class="rebirth-history">'+r.previous.slice().reverse().slice(rebirthHistoryPage*3,rebirthHistoryPage*3+3).map(p=>'<article><b>'+p.attempt+'번째 삶 · '+(p.status==='sacked'?'계약 종료':'1부 귀환')+'</b><span>리그 '+p.records.length+'경기 · 최고 '+p.division+'부</span><small>'+esc(Rebirth.memories[p.memory].name)+'</small></article>').join('')+'</div>':'<p>아직 끝난 삶이 없습니다. 이곳에는 환생 전의 마지막 기록이 남습니다.</p>';actions=(r.previous.length>3?button('history-prev','이전 기록',rebirthHistoryPage===0?'disabled':'')+button('history-next','다음 기록',(rebirthHistoryPage+1)*3>=r.previous.length?'disabled':''):'')+button('current','이번 삶으로');}
 else if(rebirthPage==='confirm'&&ended){title='다시 눈을 뜰 준비';content='<p class="rebirth-line">기억 하나를 품고, 낡은 감독실 문을 다시 엽니다.</p><p>다음은 <b>'+(r.attempt+1)+'번째 삶</b>. 토투넘 원래 18명 · 5부 첫 경기 · 초기 자금으로 돌아갑니다. 선수 성장과 영입은 초기화합니다.</p><p>요약은 회귀 기록에, 현재 구단 전체는 ‘직전 구단’에 보관합니다.</p><label for="rebirth-memory">다음 삶에 가져갈 기억<select id="rebirth-memory">'+Object.entries(Rebirth.memories).filter(([id])=>id!=='none').map(([id,m])=>'<option value="'+id+'" '+(id===rebirthSelectedMemory?'selected':'')+'>'+esc(m.name)+' · '+esc(m.text)+'</option>').join('')+'</select></label>';actions=button('restart',rebirthBusy?'새 삶을 준비하는 중…':'기억을 품고 환생',rebirthBusy?'disabled':'')+button('current','아직 기록을 더 보기');}
 else if(ended){title=r.status==='sacked'?'이번 삶의 계약이 끝났습니다':'토투넘, 마침내 1부로';content='<p class="rebirth-line">'+(r.status==='sacked'?'“미안합니다, 감독님. 여기까지인 것 같습니다.” 문이 닫히자, 익숙한 알람 소리가 들립니다. 이번에는 무엇을 다르게 할 수 있을까요?':'네 번의 계단 끝에 익숙한 함성이 들립니다. 책상 위 계약서가 빛납니다. 약속한 귀환을 이루었습니다.')+'</p>'+(r.status==='sacked'?'<p class="rebirth-note">최후통첩 3경기: 승점 '+r.warning.points+' / 3점 · 약속한 성적에 미달했습니다.</p>':'')+'<div class="rebirth-facts"><span>'+r.attempt+'번째 삶</span><span>리그 '+r.played+'경기</span><span>'+r.wins+'승 · '+r.points+'점</span><span>최고 '+r.bestDivision+'부</span></div>';actions=button('prepare','새 삶 준비 · 무료')+(r.canAppeal?button('appeal','기억으로 마지막 유예 · 무료'):'')+button('export','이번 삶 저장 파일 받기');}
 else if(r.pending){title=r.pending.title;content='<small>'+esc(r.pending.speaker)+' · '+r.played+'경기 뒤'+(r.pending.speaker==='구단주'?' · '+esc(r.contract.label):'')+'</small><p class="rebirth-line">'+esc(r.pending.line)+'</p><p>다음 리그 3경기의 약속을 정하세요. 달성하면 이사회에 여유가 생기고, 실패하면 압박이 커집니다.</p>';actions=r.pending.options.map(o=>button('choose-'+o.id,o.label+' · '+Rebirth.targetText(o))).join('');}
 else{title=r.warning?'최후통첩: 세 경기의 기회':r.attempt+'번째 삶, 아직 끝나지 않았다';content='<p class="rebirth-note">구단주 · '+esc(r.contract.label)+'</p><div class="rebirth-meter"><div><b>이사회 여유 '+r.confidence+' / 100</b><span>'+esc(r.memoryInfo.name)+'</span></div><meter min="0" max="100" low="21" high="42" optimum="80" value="'+r.confidence+'">'+r.confidence+'</meter></div>'+(r.warning?'<p class="rebirth-line">“마지막 기회입니다. 남은 '+r.warning.remaining+'경기에서 결과를 보여 주세요.”</p><p>최후통첩 승점 <b>'+r.warning.points+' / 3점</b> · 실패하면 경질됩니다.</p>':'<p class="rebirth-line">“이곳이 처음 같지 않은 건, 다음 선택이 달라질 수 있기 때문이겠죠.”</p>')+(r.mission?'<div class="rebirth-mission"><b>'+esc(r.mission.speaker)+'와의 약속</b><p>'+esc(r.mission.targetText)+' · 현재 '+r.mission.value+' · '+r.mission.remaining+'경기 남음</p></div>':'<p>리그 '+r.played+'경기 완료 · 6경기마다 도전 면담이 찾아옵니다.</p>')+(r.lastChange?'<p class="rebirth-note">최근 리그 '+esc(r.lastChange.result)+' · 여유 '+(r.lastChange.delta>0?'+':'')+r.lastChange.delta+' (약속 포함)</p>':'')+(r.timeline.length?'<p class="rebirth-note">'+esc(r.timeline.at(-1).text)+'</p>':'<p class="rebirth-note">처음부터 경질되지는 않습니다. 여유가 20 이하가 되면 만회할 세 경기를 먼저 드립니다.</p>');actions=button('close','준비하고 다음 경기로');}
 if(rebirthPage==='rules'){const items=[...content.matchAll(/<li>([\s\S]*?)<\/li>/g)].map(m=>m[1]);content='<small>규칙 '+(rebirthRulesPage+1)+' / 2</small><ol start="'+(rebirthRulesPage*3+1)+'">'+items.slice(rebirthRulesPage*3,rebirthRulesPage*3+3).map(x=>'<li>'+x+'</li>').join('')+'</ol><p class="rebirth-note">현재 환생·기억의 유예는 무료입니다. 실제 결제는 연결되지 않았습니다.</p>';actions=button('rules-next',rebirthRulesPage?'앞 페이지':'다음 페이지')+button('current','이번 삶으로');}
 rebirthDialog.innerHTML='<header><div><small>토투넘 · 환생 도전'+(r.enabled?' · '+r.attempt+'번째 삶':'')+'</small><h2 id="rebirth-title" tabindex="-1">'+esc(title)+'</h2></div><button type="button" data-rebirth="close" aria-label="환생 창 닫기">닫기</button></header><nav aria-label="환생 도전 메뉴">'+button('current','이번 삶')+button('history','회귀 기록',!r.enabled?'disabled':'')+button('rules','규칙')+'</nav><div class="rebirth-body">'+content+'</div><p class="rebirth-error" role="alert" '+(!rebirthError?'hidden':'')+'>'+esc(rebirthError)+'</p><footer>'+actions+'</footer>';
 if(rebirthDialog.open)$('rebirth-title').focus({preventScroll:true});
 const choice=$('rebirth-memory');if(choice)choice.onchange=()=>{rebirthSelectedMemory=choice.value;};
}
rebirthDialog.addEventListener('click',e=>{const id=e.target.closest('[data-rebirth]')?.dataset.rebirth;if(!id||rebirthBusy)return;if(id==='close')return closeRebirth();if(id==='rules-next'){rebirthRulesPage=1-rebirthRulesPage;renderRebirthDialog();return;}if(id==='history-prev'||id==='history-next'){rebirthHistoryPage+=id==='history-next'?1:-1;renderRebirthDialog();return;}if(['current','rules','history'].includes(id)){rebirthPage=id;rebirthRulesPage=0;rebirthHistoryPage=0;renderRebirthDialog();return;}if(id==='enable'){rebirthMutation(()=>Rebirth.enable(season));return;}if(id.startsWith('choose-')){rebirthMutation(()=>Rebirth.choose(season,id.slice(7)));return;}if(id==='appeal'){rebirthMutation(()=>Rebirth.appeal(season));return;}if(id==='prepare'){rebirthPage='confirm';renderRebirthDialog();return;}if(id==='restart')return reincarnate();if(id==='export')return exportCampaign();});
rebirthDialog.addEventListener('cancel',e=>{if(rebirthBusy)e.preventDefault();});
const rebirthRender=render;render=function(){rebirthRender();if(!appSessionStarted||view!=='club'||typeof practiceSession!=='undefined'&&practiceSession)return;const r=Rebirth.read(season),entry=$('mobile-dashboard-toggle');if(entry){entry.textContent=r.enabled?rebirthHint(r):'환생 도전 시작';entry.onclick=()=>openRebirth('current',entry);entry.setAttribute('aria-expanded',String(rebirthDialog.open));}
 if(r.enabled&&(r.status!=='active'||r.pending)){const start=$('mobile-match-action');if(start){start.textContent=rebirthHint(r);start.onclick=()=>openRebirth('current',start);}}
 const last=r.timeline?.at(-1),key=r.enabled?r.attempt+':'+r.played+':'+r.status+':'+(r.pending?'deal':last?.kind||''):null;
 if(key&&(r.status!=='active'||r.pending||last&&['warning','survived','fulfilled','missed'].includes(last.kind)&&last.after===r.played)&&!rebirthSeen.has(key))rebirthOffer={season,key};
};
setInterval(()=>{if(!rebirthOffer||rebirthOffer.season!==season||document.hidden||!appSessionStarted||view!=='club'||document.querySelector('dialog[open]')||managerGuideActive)return;rebirthSeen.add(rebirthOffer.key);rebirthOffer=null;openRebirth();},250);
const rebirthAdvance=advanceMatchWithFeedback;advanceMatchWithFeedback=function(){if(state===season.match){try{Rebirth.assertPlayable(season);}catch{openRebirth();return;}}return rebirthAdvance();};
const rebirthLaunch=renderAppShell;renderAppShell=function(){rebirthLaunch();if(!appSessionStarted&&season.rebirth&&Rebirth.read(season).status!=='active'&&!launchBusy)$('launch-continue').textContent='이번 삶의 결말 보기';};
const rebirthGuide=renderManagerGuide;renderManagerGuide=function(){rebirthGuide();if(!season.rebirth)return;const r=Rebirth.read(season);if(managerGuideStep===0&&r.attempt>1){const intro=StoryRebirth.opening(season);$('manager-guide-title').textContent=intro.title;$('manager-guide-copy').textContent=intro.text;}if(managerGuideStep===1)$('manager-guide-copy').textContent+='\n\n구단주: “이사회 여유가 바닥나면 마지막 세 경기입니다. 기회를 놓치면 경질이지요.”\n경질 뒤에는 기억 하나를 품고 무료로 다시 시작합니다.';};

const rebirthAction=action;action=function(fn){if(season.rebirth&&state===season.match&&Rebirth.read(season).status!=='active'){openRebirth();return snapshot();}return rebirthAction(fn);};
